-- 002: duplicate-submit protection + CRM retry queue ("outbox").
-- client_id: random id generated by the browser per form load. A double tap / network retry
--            sends the same id, so the unique index returns the existing lead instead of a duplicate.
-- crm_attempts / crm_next_attempt_at: let a background worker retry failed CRM pushes with backoff.
ALTER TABLE leads ADD COLUMN IF NOT EXISTS client_id TEXT;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS crm_attempts INTEGER NOT NULL DEFAULT 0;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS crm_next_attempt_at TIMESTAMPTZ;
CREATE UNIQUE INDEX IF NOT EXISTS leads_client_id_key ON leads (client_id);
CREATE INDEX IF NOT EXISTS leads_crm_queue_idx ON leads (crm_status, crm_next_attempt_at);
